 "content": "def transform(grid):
    """Extend adjacent equal-color diagonal pairs upward to the top edge."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dc in (-1, 1):
                c2 = c + dc
                if 0 <= c2 < w and grid[r + 1][c2] == color:
                    rr, cc = r - 1, c - dc
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = color
                        rr -= 1
                        cc -= dc
    return out
