 "content": "def transform(grid):
    """Extend diagonal runs, resolving a small crossed-color motif by the shorter run."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    runs = []
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                cells = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    cells.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(cells) >= 2:
                    runs.append((color, dr, dc, cells))
    # In a tightly interlocked diagonal motif, an extended run may coincide
    # with a separate short diagonal marker. Keep projections for the short
    # line in that local crossing configuration.
    skip = set()
    for i, a in enumerate(runs):
        for j, b in enumerate(runs):
            if i == j or a[0] == b[0]:
                continue
            ca, cb = a[3], b[3]
            if len(ca) >= 3 and len(cb) == 2:
                near = any(abs(r1-r2) <= 1 and abs(c1-c2) <= 1
                           for r1,c1 in ca for r2,c2 in cb)
                if near:
                    skip.add(i)
    out = [row[:] for row in grid]
    for idx, (color, dr, dc, cells) in enumerate(runs):
        if idx in skip:
            continue
        for rr, cc, sr, sc in ((cells[0][0]-dr, cells[0][1]-dc, -dr, -dc),
                               (cells[-1][0]+dr, cells[-1][1]+dc, dr, dc)):
            while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                out[rr][cc] = color
                rr += sr
                cc += sc
    return out
